import re, json, csv, hashlib

base = "."
files = {
    "md": f"{base}/audit-v2-s01-t04-evidence-01.md",
    "jsonl": f"{base}/audit-v2-s01-t04-evidence-02.jsonl",
    "csv": f"{base}/audit-v2-s01-t04-evidence-03.csv",
    "yaml": f"{base}/audit-v2-s01-t04-evidence-04.yaml",
    "log": f"{base}/audit-v2-s01-t04-evidence-05.log",
}

def parse_md(path):
    out = {}
    with open(path) as f:
        for line in f:
            m = re.match(r"- \*\*(audit-v2-s01-t04-\d{6})\*\* \| System: ([\w-]+) \| Status: ([\w-]+) \|", line)
            if m:
                out[m.group(1)] = (m.group(2), m.group(3))
    return out

def parse_jsonl(path):
    out = {}
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            rec = json.loads(line)
            out[rec["case"]] = (rec["system"], rec["status"])
    return out

def parse_csv(path):
    out = {}
    with open(path, newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            out[row["case"]] = (row["system"], row["status"])
    return out

def parse_yaml(path):
    out = {}
    case = system = status = None
    with open(path) as f:
        for line in f:
            line = line.rstrip("\n")
            m = re.match(r"- case: (audit-v2-s01-t04-\d{6})", line)
            if m:
                case = m.group(1)
                continue
            m = re.match(r"\s+system: ([\w-]+)", line)
            if m:
                system = m.group(1)
                continue
            m = re.match(r"\s+status: ([\w-]+)", line)
            if m:
                status = m.group(1)
                if case:
                    out[case] = (system, status)
                case = system = status = None
    return out

def parse_log(path):
    out = {}
    with open(path) as f:
        for line in f:
            m = re.match(r"case=(audit-v2-s01-t04-\d{6}) system=([\w-]+) status=([\w-]+) note=", line)
            if m:
                out[m.group(1)] = (m.group(2), m.group(3))
    return out

parsed = {
    "md": parse_md(files["md"]),
    "jsonl": parse_jsonl(files["jsonl"]),
    "csv": parse_csv(files["csv"]),
    "yaml": parse_yaml(files["yaml"]),
    "log": parse_log(files["log"]),
}

for name, d in parsed.items():
    print(name, "parsed records:", len(d))

names = list(parsed.keys())
for i in range(len(names)):
    for j in range(i+1, len(names)):
        a, b = names[i], names[j]
        common = set(parsed[a]) & set(parsed[b])
        mismatches = [c for c in common if parsed[a][c] != parsed[b][c]]
        print(f"{a} vs {b}: common={len(common)} mismatches={len(mismatches)}")
        if mismatches[:5]:
            print("  sample mismatches:", mismatches[:5])
EOF

