    out = {}
    with open(path) as f:
        for line in f:
            m = re.match(r"- \*\*(audit-v2-s01-t04-\d{6})\*\*.*Evidence: (.*)$", line)
            if m:
                out[m.group(1)] = m.group(2).strip()
    return out

def parse_jsonl_notes(path):
    out = {}
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line: continue
            rec = json.loads(line)
            out[rec["case"]] = rec["note"]
    return out

def parse_csv_notes(path):
    out = {}
    with open(path, newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            out[row["case"]] = row["note"]
    return out

def parse_yaml_notes(path):
    out = {}
    case = None
    with open(path) as f:
        for line in f:
            line = line.rstrip("\n")
            m = re.match(r"- case: (audit-v2-s01-t04-\d{6})", line)
            if m:
                case = m.group(1); continue
            m = re.match(r'\s+note: "(.*)"', line)
            if m and case:
                out[case] = m.group(1)
                case = None
    return out

def parse_log_notes(path):
    out = {}
    with open(path) as f:
        for line in f:
            m = re.match(r'case=(audit-v2-s01-t04-\d{6}) system=[\w-]+ status=[\w-]+ note="(.*)"$', line)
            if m:
                out[m.group(1)] = m.group(2)
    return out

md = parse_md_notes("audit-v2-s01-t04-evidence-01.md")
