        a, b = names[i], names[j]
        common = set(sets[a]) & set(sets[b])
        mism = [c for c in common if sets[a][c] != sets[b][c]]
        print(f"{a} vs {b}: common={len(common)} note-mismatches={len(mism)}")

# Check the 4-cycle rotation pattern holds for md (system, status) by case number
import itertools
cycle_system = ["linux-x86_64","windows-x86_64","freebsd-x86_64","macos-arm64"]
cycle_status = ["review","recorded","follow-up","supported"]

def parse_md_pairs(path):
    out = {}
    with open(path) as f:
        for line in f:
            m = re.match(r"- \*\*(audit-v2-s01-t04-(\d{6}))\*\* \| System: ([\w-]+) \| Status: ([\w-]+) \|", line)
            if m:
                out[int(m.group(2))] = (m.group(3), m.group(4))
    return out

pairs = parse_md_pairs("audit-v2-s01-t04-evidence-01.md")
violations = []
for n, (sys_, stat_) in pairs.items():
    expected_sys = cycle_system[(n-1) % 4]
    expected_stat = cycle_status[(n-1) % 4]
    if (sys_, stat_) != (expected_sys, expected_stat):
        violations.append((n, sys_, stat_, expected_sys, expected_stat))
print("md rotation violations:", len(violations), violations[:5])
