import re, json, csv

def parse_md(path):
    out = {}
    with open(path) as f:
        for line in f:
            m = re.match(r"- \*\*(audit-v2-s01-t05-\d{6})\*\* \| System: ([\w-]+) \| Status: ([\w-]+) \| Evidence: (.*)$", line)
            if m:
                out[m.group(1)] = (m.group(2), m.group(3), m.group(4).strip())
    return out

def parse_jsonl(path):
    out = {}
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line: continue
            rec = json.loads(line)
            out[rec["case"]] = (rec["system"], rec["status"], rec["note"])
    return out

def parse_csv(path):
    out = {}
    with open(path, newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            out[row["case"]] = (row["system"], row["status"], row["note"])
    return out

def parse_yaml(path):
    out = {}
    case = system = status = None
    with open(path) as f:
        for line in f:
            line = line.rstrip("\n")
            m = re.match(r"- case: (audit-v2-s01-t05-\d{6})", line)
            if m:
                case = m.group(1); continue
            m = re.match(r"\s+system: ([\w-]+)", line)
            if m:
                system = m.group(1); continue
            m = re.match(r"\s+status: ([\w-]+)", line)
            if m:
                status = m.group(1); continue
            m = re.match(r'\s+note: "(.*)"', line)
            if m and case:
                out[case] = (system, status, m.group(1))
                case = system = status = None
    return out

def parse_log(path):
    out = {}
    with open(path) as f:
        for line in f:
            m = re.match(r'case=(audit-v2-s01-t05-\d{6}) system=([\w-]+) status=([\w-]+) note="(.*)"$', line)
            if m:
                out[m.group(1)] = (m.group(2), m.group(3), m.group(4))
    return out

sets = {
    "md": parse_md("audit-v2-s01-t05-evidence-01.md"),
    "jsonl": parse_jsonl("audit-v2-s01-t05-evidence-02.jsonl"),
    "csv": parse_csv("audit-v2-s01-t05-evidence-03.csv"),
    "yaml": parse_yaml("audit-v2-s01-t05-evidence-04.yaml"),
    "log": parse_log("audit-v2-s01-t05-evidence-05.log"),
}

for name, d in sets.items():
    print(name, "parsed records:", len(d))

names = list(sets.keys())
for i in range(len(names)):
    for j in range(i+1, len(names)):
        a, b = names[i], names[j]
        common = set(sets[a]) & set(sets[b])
        mism = [c for c in common if sets[a][c] != sets[b][c]]
        print(f"{a} vs {b}: common={len(common)} mismatches={len(mism)}")

# rotation check on md
cycle_system = ["linux-x86_64","windows-x86_64","freebsd-x86_64","macos-arm64"]
cycle_status = ["recorded","follow-up","supported","review"]
violations = []
for case, (sys_, stat_, note) in sets["md"].items():
    n = int(case.split("-")[-1])
    exp_sys = cycle_system[(n-1) % 4]
    exp_stat = cycle_status[(n-1) % 4]
    if (sys_, stat_) != (exp_sys, exp_stat):
        violations.append((n, sys_, stat_, exp_sys, exp_stat))
print("md rotation violations:", len(violations), violations[:5])
EOF

