cd /private/var/folders/sp/k4h4yd5j4bj0zwbwzps0yj8c0000gp/T/lcm-live-53xcp9k9/audit-v2-s01/maintenance/inputs/audit-v2-s01/load-balancer-matrix && python3 << 'EOF'
import re, json, csv

def parse_md(path):
    recs = {}
    with open(path) as f:
        for line in f:
            m = re.match(r'- \*\*(?P<case>\S+)\*\* \| System: (?P<system>\S+) \| Status: (?P<status>\S+) \| Evidence: (?P<note>.*)$', line.strip())
            if m:
                d = m.groupdict()
                recs[d['case']] = {'system': d['system'], 'status': d['status'], 'note': d['note']}
    return recs

def parse_jsonl(path):
    recs = {}
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            d = json.loads(line)
            recs[d['case']] = {'system': d['system'], 'status': d['status'], 'note': d['note']}
    return recs

def parse_csv(path):
    recs = {}
    with open(path, newline='') as f:
        for row in csv.DictReader(f):
            recs[row['case']] = {'system': row['system'], 'status': row['status'], 'note': row['note']}
    return recs

def parse_yaml(path):
    recs = {}
    cur = {}
    with open(path) as f:
        for line in f:
            line = line.rstrip('\n')
            if line.startswith('- case:'):
                if cur:
                    recs[cur['case']] = {'system': cur['system'], 'status': cur['status'], 'note': cur['note']}
                cur = {'case': line.split('- case:')[1].strip()}
            elif line.strip().startswith('system:'):
                cur['system'] = line.split('system:')[1].strip()
            elif line.strip().startswith('status:'):
                cur['status'] = line.split('status:')[1].strip()
            elif line.strip().startswith('note:'):
                cur['note'] = line.split('note:',1)[1].strip().strip('"')
        if cur:
            recs[cur['case']] = {'system': cur['system'], 'status': cur['status'], 'note': cur['note']}
    return recs

def parse_log(path):
    recs = {}
    pat = re.compile(r'case=(?P<case>\S+) system=(?P<system>\S+) status=(?P<status>\S+) note="(?P<note>.*)"$')
    with open(path) as f:
        for line in f:
            m = pat.match(line.strip())
            if m:
                d = m.groupdict()
                recs[d['case']] = {'system': d['system'], 'status': d['status'], 'note': d['note']}
    return recs

md = parse_md('audit-v2-s01-t07-evidence-01.md')
jsonl = parse_jsonl('audit-v2-s01-t07-evidence-02.jsonl')
csvd = parse_csv('audit-v2-s01-t07-evidence-03.csv')
yaml = parse_yaml('audit-v2-s01-t07-evidence-04.yaml')
log = parse_log('audit-v2-s01-t07-evidence-05.log')

files = {'md': md, 'jsonl': jsonl, 'csv': csvd, 'yaml': yaml, 'log': log}
for name, recs in files.items():
    ids = sorted(recs.keys())
    print(name, 'count=', len(recs), 'min=', ids[0], 'max=', ids[-1])

# check for gaps in each
import re as re2
def num(c):
    return int(c.split('-')[-1])

for name, recs in files.items():
    nums = sorted(num(c) for c in recs.keys())
    expected = list(range(1, nums[-1]+1))
    missing = set(expected) - set(nums)
    print(name, 'missing case numbers:', sorted(missing) if missing else 'none')

# pairwise comparison on overlapping keys
names = list(files.keys())
for i in range(len(names)):
    for j in range(i+1, len(names)):
        a, b = names[i], names[j]
        common = set(files[a].keys()) & set(files[b].keys())
        mismatches = []
        for c in common:
            if files[a][c] != files[b][c]:
                mismatches.append(c)
        print(f'{a} vs {b}: common={len(common)} mismatches={len(mismatches)}', mismatches[:5])

# rotation check across md (or any) full range
seq_system = ['linux-x86_64','windows-x86_64','freebsd-x86_64','macos-arm64']
seq_status = ['supported','review','recorded','follow-up']
violations = 0
for c in sorted(md.keys(), key=num):
    n = num(c)
    exp_sys = seq_system[(n-1) % 4]
    exp_status = seq_status[(n-1) % 4]
    if md[c]['system'] != exp_sys or md[c]['status'] != exp_status:
        violations += 1
        print('violation', c, md[c])
print('rotation violations (md, 143 records):', violations)

# also verify csv covers the extra range 138-162 consistently
extra = [c for c in csvd if num(c) > 143]
extra_violations = 0
for c in sorted(extra, key=num):
    n = num(c)
    exp_sys = seq_system[(n-1) % 4]
    exp_status = seq_status[(n-1) % 4]
    if csvd[c]['system'] != exp_sys or csvd[c]['status'] != exp_status:
        extra_violations += 1
print('csv-only extra range (144-162) count:', len(extra), 'rotation violations:', extra_violations)

log_extra = [c for c in log if num(c) > 143]
print('log-only extra range (144-150) count:', len(log_extra))
log_extra_violations = 0
for c in sorted(log_extra, key=num):
    n = num(c)
    exp_sys = seq_system[(n-1) % 4]
    exp_status = seq_status[(n-1) % 4]
    if log[c]['system'] != exp_sys or log[c]['status'] != exp_status:
        log_extra_violations += 1
print('log extra range rotation violations:', log_extra_violations)
EOF

