D=/private/var/folders/sp/k4h4yd5j4bj0zwbwzps0yj8c0000gp/T/lcm-live-53xcp9k9/audit-v2-s01/maintenance/inputs/audit-v2-s01/rollout-windows
python3 - "$D" <<'PYEOF'
import sys, re, json, csv

D = sys.argv[1]

def parse_md(path):
    recs = {}
    pat = re.compile(r'\*\*(audit-v2-s01-t11-\d+)\*\* \| System: ([\w.-]+) \| Status: ([\w-]+) \| Evidence: (.*)$')
    with open(path) as f:
        for line in f:
            m = pat.search(line)
            if m:
                cid, sysname, status, note = m.groups()
                recs[cid] = {"system": sysname, "status": status, "note": note.strip()}
    return recs

def parse_jsonl(path):
    recs = {}
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            obj = json.loads(line)
            recs[obj["case"]] = {"system": obj["system"], "status": obj["status"], "note": obj["note"]}
    return recs

def parse_csv(path):
    recs = {}
    with open(path, newline='') as f:
        reader = csv.DictReader(f)
        for row in reader:
            recs[row["case"]] = {"system": row["system"], "status": row["status"], "note": row["note"]}
    return recs

def parse_yaml(path):
    recs = {}
    cur = {}
    with open(path) as f:
        for line in f:
            line = line.rstrip("\n")
            if line.startswith("- case:"):
                if cur.get("case"):
                    recs[cur["case"]] = {"system": cur["system"], "status": cur["status"], "note": cur["note"]}
                cur = {"case": line.split("- case:")[1].strip()}
            elif line.strip().startswith("system:"):
                cur["system"] = line.split("system:")[1].strip()
            elif line.strip().startswith("status:"):
                cur["status"] = line.split("status:")[1].strip()
            elif line.strip().startswith("note:"):
                note = line.split("note:", 1)[1].strip()
                if note.startswith('"') and note.endswith('"'):
                    note = note[1:-1]
                cur["note"] = note
        if cur.get("case"):
            recs[cur["case"]] = {"system": cur["system"], "status": cur["status"], "note": cur["note"]}
    return recs

def parse_log(path):
    recs = {}
    pat = re.compile(r'case=(\S+) system=(\S+) status=(\S+) note="(.*)"$')
    with open(path) as f:
        for line in f:
            m = pat.search(line)
            if m:
                cid, sysname, status, note = m.groups()
                recs[cid] = {"system": sysname, "status": status, "note": note}
    return recs

files = {
    "md": parse_md(f"{D}/audit-v2-s01-t11-evidence-01.md"),
    "jsonl": parse_jsonl(f"{D}/audit-v2-s01-t11-evidence-02.jsonl"),
    "csv": parse_csv(f"{D}/audit-v2-s01-t11-evidence-03.csv"),
    "yaml": parse_yaml(f"{D}/audit-v2-s01-t11-evidence-04.yaml"),
    "log": parse_log(f"{D}/audit-v2-s01-t11-evidence-05.log"),
}

for name, recs in files.items():
    ids = sorted(recs.keys())
    nums = [int(i.split("-")[-1]) for i in ids]
    print(f"{name}: count={len(recs)} min={min(nums):06d} max={max(nums):06d}")
    expected = set(range(min(nums), max(nums)+1))
    actual = set(nums)
    missing = sorted(expected - actual)
    if missing:
        print(f"  MISSING within range: {missing}")

print()
names = list(files.keys())
for i in range(len(names)):
    for j in range(i+1, len(names)):
        a, b = names[i], names[j]
        shared = set(files[a].keys()) & set(files[b].keys())
        mismatches = []
        for cid in shared:
            ra, rb = files[a][cid], files[b][cid]
            if ra != rb:
                mismatches.append((cid, ra, rb))
        print(f"{a} vs {b}: shared={len(shared)} mismatches={len(mismatches)}")
        for m in mismatches[:5]:
            print("   ", m)

print()
shortest_name = min(files, key=lambda n: max(int(i.split("-")[-1]) for i in files[n]))
shortest = files[shortest_name]
max_shortest = max(int(i.split("-")[-1]) for i in shortest)
print("shortest file:", shortest_name, "max:", max_shortest)

ids_sorted = sorted(shortest.keys(), key=lambda x: int(x.split("-")[-1]))
pattern = {}
violations = []
for cid in ids_sorted:
    n = int(cid.split("-")[-1])
    pos = ((n - 1) % 4) + 1
    rec = shortest[cid]
    key = (rec["system"], rec["status"])
    if pos not in pattern:
        pattern[pos] = key
    elif pattern[pos] != key:
        violations.append((cid, pos, key, pattern[pos]))
print("rotation pattern (from shortest file):", pattern)
print("violations in shortest file:", len(violations))

for name in files:
    if name == shortest_name:
        continue
    recs = files[name]
    ids_sorted = sorted(recs.keys(), key=lambda x: int(x.split("-")[-1]))
    extra_violations = []
    for cid in ids_sorted:
        n = int(cid.split("-")[-1])
        if n <= max_shortest:
            continue
        pos = ((n - 1) % 4) + 1
        rec = recs[cid]
        key = (rec["system"], rec["status"])
        if pattern.get(pos) != key:
            extra_violations.append((cid, pos, key, pattern.get(pos)))
    print(f"{name} extra-range (>{max_shortest}) violations:", extra_violations)
PYEOF

