python3 <<'PYEOF'
import re, json, csv

base = "/private/var/folders/sp/k4h4yd5j4bj0zwbwzps0yj8c0000gp/T/lcm-live-53xcp9k9/audit-v2-s01/maintenance/inputs/audit-v2-s01/proxy-support-tickets"

def parse_md(path):
    recs = {}
    with open(path) as f:
        for line in f:
            m = re.match(r"- \*\*(audit-v2-s01-t14-\d+)\*\* \| System: (\S+) \| Status: (\S+) \| Evidence: (.*)$", line.strip())
            if m:
                case, system, status, evidence = m.groups()
                recs[case] = {"system": system, "status": status, "note": evidence}
    return recs

def parse_jsonl(path):
    recs = {}
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            d = json.loads(line)
            recs[d["case"]] = {"system": d["system"], "status": d["status"], "note": d["note"]}
    return recs

def parse_csv(path):
    recs = {}
    with open(path, newline="") as f:
        for row in csv.DictReader(f):
            recs[row["case"]] = {"system": row["system"], "status": row["status"], "note": row["note"]}
    return recs

def parse_yaml(path):
    recs = {}
    with open(path) as f:
        lines = f.readlines()
    cur = None
    for line in lines:
        line = line.rstrip("\n")
        m = re.match(r"- case: (\S+)", line)
        if m:
            cur = m.group(1)
            recs[cur] = {}
            continue
        m = re.match(r"  system: (\S+)", line)
        if m and cur:
            recs[cur]["system"] = m.group(1)
            continue
        m = re.match(r"  status: (\S+)", line)
        if m and cur:
            recs[cur]["status"] = m.group(1)
            continue
        m = re.match(r'  note: "(.*)"', line)
        if m and cur:
            recs[cur]["note"] = m.group(1)
            continue
    return recs

def parse_log(path):
    recs = {}
    with open(path) as f:
        for line in f:
            line = line.strip()
            m = re.match(r'case=(\S+) system=(\S+) status=(\S+) note="(.*)"$', line)
            if m:
                case, system, status, note = m.groups()
                recs[case] = {"system": system, "status": status, "note": note}
    return recs

files = {
    "md": parse_md(f"{base}/audit-v2-s01-t14-evidence-01.md"),
    "jsonl": parse_jsonl(f"{base}/audit-v2-s01-t14-evidence-02.jsonl"),
    "csv": parse_csv(f"{base}/audit-v2-s01-t14-evidence-03.csv"),
    "yaml": parse_yaml(f"{base}/audit-v2-s01-t14-evidence-04.yaml"),
    "log": parse_log(f"{base}/audit-v2-s01-t14-evidence-05.log"),
}

def case_num(c):
    return int(c.split("-")[-1])

for name, recs in files.items():
    nums = sorted(case_num(c) for c in recs)
    print(f"{name}: count={len(recs)} min={nums[0]} max={nums[-1]}")
    expected = list(range(nums[0], nums[-1]+1))
    missing = sorted(set(expected) - set(nums))
    print(f"  gaps: {missing if missing else 'none'}")

names = list(files.keys())
print()
print("Pairwise comparisons (on overlapping cases):")
mismatches_found = False
for i in range(len(names)):
    for j in range(i+1, len(names)):
        a, b = names[i], names[j]
        common = set(files[a]) & set(files[b])
        mismatches = []
        for c in common:
            if files[a][c] != files[b][c]:
                mismatches.append(c)
        print(f"  {a} vs {b}: {len(common)} common cases, {len(mismatches)} mismatches")
        if mismatches:
            mismatches_found = True
            print(f"    mismatched cases: {mismatches}")

print()
print("mismatches_found:", mismatches_found)

jsonl = files["jsonl"]
nums_jsonl = sorted(case_num(c) for c in jsonl)
pattern = {}
violations = []
for n in nums_jsonl:
    pos = ((n - 1) % 4) + 1
    case = f"audit-v2-s01-t14-{n:06d}"
    sys_, status = jsonl[case]["system"], jsonl[case]["status"]
    if pos not in pattern:
        pattern[pos] = (sys_, status)
    else:
        if pattern[pos] != (sys_, status):
            violations.append((case, pos, (sys_, status), pattern[pos]))

print()
print("Rotation pattern (from jsonl):")
for pos in sorted(pattern):
    print(f"  position {pos}: {pattern[pos]}")
print("violations within jsonl:", violations if violations else "none")

all_violations = []
for name, recs in files.items():
    for case, rec in recs.items():
        n = case_num(case)
        pos = ((n - 1) % 4) + 1
        expected = pattern[pos]
        actual = (rec["system"], rec["status"])
        if expected != actual:
            all_violations.append((name, case, pos, expected, actual))

print()
print("Rotation pattern violations across all files:", all_violations if all_violations else "none")
PYEOF

